import{_ as p,a0 as o,w as l,s as u,ao as e,I as a,x as n,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 黑話解釋：什麼是上游和下游？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：什麼是上游和下游？ | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：什麼是上游和下游？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：什麼是上游和下游？ | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220124 Linux Jargon Buster- What are Upstream and Downstream","title":"Linux 黑話解釋：什麼是上游和下游？","tag":"202201","desc":""},"relativePath":"202201/20220124 Linux Jargon Buster- What are Upstream and Downstream.md","filePath":"[post].md"}'),d={name:"202201/20220124 Linux Jargon Buster- What are Upstream and Downstream.md"};function m(x,t,f,b,L,g){const r=o("Link");return l(),u("div",null,[t[28]||(t[28]=e('<h1 id="linux-黑話解釋-什麼是上游和下游" tabindex="-1">Linux 黑話解釋：什麼是上游和下游？ <a class="header-anchor" href="#linux-黑話解釋-什麼是上游和下游" aria-label="Permalink to “Linux 黑話解釋：什麼是上游和下游？”">​</a></h1><p>“<ruby>上游<rt>upstream</rt></ruby>” 和 “<ruby>下游<rt>downstream</rt></ruby>”這兩個術語是相當模糊的，我認為一般人並不會真正使用它們。如果你只是一個 Linux 用户，並且不編寫或維護軟件，那麼很有可能這些術語對你來説毫無意義，但它們對 Linux 世界中各個社區之間的交流方式有益的。</p><p>這些術語被用於網絡、編程、內核，甚至在非計算機領域，如供應鏈。當我們談論上游和下游的時候，討論背景是很重要的。</p><p>在其最簡單的形式中，上游和下游是信息流動的方向。</p><p>由於我們都是在連接到互聯網的情況下閲讀這篇文章的，讓我們看看適用於互聯網服務提供商（ISP）的上游/下游例子。這裏，ISP 關注的是流量。上游流量是指數據是從不同的 ISP 的用户處傳來的。例如，如果你有一個提供訂閲通訊的網站，我發送的訂閲信息就是上游數據。</p><p>下游流量是指從一個用户發送到不同 ISP 的另一個用户的數據，它被認為是下游流量。使用同樣的訂閲例子，假設我的訂閲請求被批准，我在一封郵件中收到“歡迎”説明，在又一封郵件中收到最新的新聞簡報。在這種情況下，數據是順流而下的，因為它是由你（好吧，可能是作為代表你進行操作的自動化軟件）發送給我，一個來自另外 ISP 的用户。</p><p>總結：我需要或想要的東西（你的通訊）是上游的。你提供給我的東西（歡迎詞和實際的通訊）是下游的。</p><p>數據是在上游還是在下游，對我們用户來説可能並不重要，但對監控帶寬使用的服務器管理員，以及<ruby>發行商<rt>distributor</rt></ruby>（發行版的製作者）和程序員來説卻很重要。</p><p>在 Linux 世界裏，上游和下游有兩個主要背景。一個是關於內核的，另一個是關於應用程序的。還有其他的，但我希望我可以通過這兩個來表達我的想法。</p><h3 id="linux-內核背景下的上游和下游" tabindex="-1">Linux 內核背景下的上游和下游 <a class="header-anchor" href="#linux-內核背景下的上游和下游" aria-label="Permalink to “Linux 內核背景下的上游和下游”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/upstream-downstream.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>Linux <em>就是</em> 內核。在創建發行版時，Linux 發行版首先使用未經修改的內核源代碼。然後添加必要的補丁，對內核進行配置。內核的配置是基於發行版想要提供的功能和選項。一旦決定了，就相應地創建了內核。</p><p>原始內核來自發行版的上游。當發行版得到源代碼時，它就流向下游。一旦發行版得到了內核代碼，它就會留在發行商那裏，同時對它進行改造。它仍然是我們用户的上游，直到它準備好被髮布。</p>',13)),a("p",null,[t[2]||(t[2]=n("發行版創建的內核版本將添加補丁和啓用某些功能和選項。這種配置是由發行商決定的。這就是為什麼有幾種 Linux 流派的原因，例如，",-1)),i(r,{href:"https://www.debian.org/"},{default:s(()=>[...t[0]||(t[0]=[n("Debian",-1)])]),_:1}),t[3]||(t[3]=n(" 與 ",-1)),i(r,{href:"https://www.redhat.com/"},{default:s(()=>[...t[1]||(t[1]=[n("Red Hat",-1)])]),_:1}),t[4]||(t[4]=n("。發行商會決定向他們的用户羣提供哪些選項，並相應地編譯內核。",-1))]),t[29]||(t[29]=a("p",null,"一旦這項工作完成，它就會放在一個倉庫中準備發佈，我們就可以獲得一份副本。這個副本向下遊流向我們。",-1)),t[30]||(t[30]=a("p",null,"同樣地，如果發行商發現了內核中的一個錯誤，修復了它，然後將補丁發送給內核開發者，這樣他們就可以為下游的每個人修補內核。這被稱為對上游的貢獻，因為這裏的流量是向上流向原始來源的。",-1)),t[31]||(t[31]=a("h3",{id:"在應用程序背景下的上游和下游",tabindex:"-1"},[n("在應用程序背景下的上游和下游 "),a("a",{class:"header-anchor",href:"#在應用程序背景下的上游和下游","aria-label":"Permalink to “在應用程序背景下的上游和下游”"},"​")],-1)),t[32]||(t[32]=a("p",null,"同樣，從技術上講，Linux 是內核，其他都是附加軟件。發行商也會在他們的項目中加入額外的軟件。在這種情況下，有幾個上游。一個發行版可以包含任何數量的應用程序，如 X、KDE、Gnome 等等。",-1)),a("p",null,[t[6]||(t[6]=n("讓我們想像一下，你在使用 ",-1)),i(r,{href:"https://www.nano-editor.org/"},{default:s(()=>[...t[5]||(t[5]=[n("nano",-1)])]),_:1}),t[7]||(t[7]=n(" 編輯器時發現它不能正常工作，於是你向發行版提交了一份錯誤報告。發行商的程序員會查看它，如果發現他們在 nano 中插入了一個錯誤，他們將修復它並在其倉庫中發佈一個新版本。如果他們發現不是他們製造了這個錯誤，發行商將向上遊的 nano 程序員提交一份錯誤報告。",-1))]),a("p",null,[t[10]||(t[10]=n("當涉及到像錯誤報告、功能請求等事情時，最好是將它們發送到上游的發行商那裏，因為他們維護着你所使用的發行版的內核和附加應用程序。例如，我在幾台機器上使用一個叫做 ",-1)),i(r,{href:"https://q4os.org/"},{default:s(()=>[...t[8]||(t[8]=[n("Q4OS",-1)])]),_:1}),t[11]||(t[11]=n(" 的發行版。如果我發現一個程序中的錯誤，我會把它報告給 Q4OS 的人。如果你碰巧使用的是 ",-1)),i(r,{href:"https://linuxmint.com/"},{default:s(()=>[...t[9]||(t[9]=[n("Mint",-1)])]),_:1}),t[12]||(t[12]=n("，你會把它報告給 Mint 項目。",-1))]),t[33]||(t[33]=e('<p>比如説，如果你在一個普通的 Linux 論壇上發佈一個問題，而你提到你在使用 Mint，你肯定會得到這樣的回覆。“這個問題最好在 Mint 論壇上處理”。用之前的 nano 錯誤的例子，有可能是 Mint 的程序員對 nano 進行了修改，使其在他們的發行版中運行得更好。如果他們確實犯了一個錯誤，他們會想知道這個錯誤，而且在犯了這個錯誤之後，他們會是修復它的人。</p><p>一旦修復，更新的程序就會被放入你可以使用的倉庫。當你得到更新時，它就會順流而下到你那裏，像這樣：</p><ul><li>如果發行商進行了修復，新版本就會在發行倉庫中提供。</li><li>如果該應用程序的程序員進行了修復，它將被髮送到測試新代碼的發行商那裏。一旦發現它工作正常，它就會被放在倉庫中，向下遊流去。</li></ul><h3 id="自動流向下游" tabindex="-1">自動流向下游 <a class="header-anchor" href="#自動流向下游" aria-label="Permalink to “自動流向下游”">​</a></h3><p>曾經有一段時間，用户得自己獲取更新。用户會得到更新的源代碼並編譯一個新的可執行文件。隨着時間的推移，像 <code>apt</code> 這樣的工具被創造出來，允許用户從軟件庫中提取更新的二進制文件（可執行文件）。<code>apt</code> 程序是 Debian 的，但其他發行版也有他們自己的用於此用途的類似程序。</p><p>像 <code>apt</code> 這樣的程序負責處理上游/下游的工作。如果你用升級選項運行 <code>apt</code>，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>它將查看（上游）發行倉庫，找到任何需要的更新包，並將它們拉到你的機器上（下游）並安裝它們。</p><p>有些發行版會更進一步。發行版的程序員和維護者總是在檢查他們的產品。很多時候，應用程序的程序員會對他們的程序進行改進。系統庫會經常更新，安全漏洞也會被堵上，等等。這些更新會提供給發行商，然後由發行商在發行倉庫中提供新的版本。</p><p>與其讓你每天運行 <code>apt</code>，一些發行版會提醒你有可用的更新並詢問你是否需要它們。如果你想要，只要接受，更新就會被髮送到你的機器上並安裝。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>上游和下游實際上只是數據流的方向。這個數據在上游或下游流動的方式取決於最終需要誰來處理它。基本上，程序員是上游，用户是下游。</p><p>同樣，作為用户，我們真的不需要關心這些術語，但這些概念確實有助於軟件的開發和維護。通過將工作引向適當的小組，避免了重複工作。這也確保了標準的維護。例如，Chrome 瀏覽器可能需要做一些細微的改變，以便在某個發行版上運行，但它的核心是 Chrome 瀏覽器，它的外觀和行為都不會有大的變化。</p><p>如果你發現你的發行版中的任何程序有錯誤，只需向發行版的維護者報告，這通常是通過他們的網站進行的。你將會把它發送到上游，但你是否記得你在向上遊發送報告並不重要。</p><hr>',15)),a("p",null,[t[14]||(t[14]=n("via: ",-1)),i(r,{href:"https://itsfoss.com/upstream-and-downstream-linux/"},{default:s(()=>[...t[13]||(t[13]=[n("https://itsfoss.com/upstream-and-downstream-linux/",-1)])]),_:1})]),a("p",null,[t[19]||(t[19]=n("作者：",-1)),i(r,{href:"https://itsfoss.com/author/bill/"},{default:s(()=>[...t[15]||(t[15]=[n("Bill Dyer",-1)])]),_:1}),t[20]||(t[20]=n(" 選題：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[16]||(t[16]=[n("lujun9972",-1)])]),_:1}),t[21]||(t[21]=n(" 譯者：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1}),t[22]||(t[22]=n(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[18]||(t[18]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[25]||(t[25]=n("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[23]||(t[23]=[n("LCTT",-1)])]),_:1}),t[26]||(t[26]=n(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:s(()=>[...t[24]||(t[24]=[n("Linux中國",-1)])]),_:1}),t[27]||(t[27]=n(" 榮譽推出",-1))])])}const k=p(d,[["render",m]]);export{C as __pageData,k as default};
